const mongoose = require('mongoose');
const EventStore = require('../models/EventStore');
const ShipmentReadModel = require('../models/ShipmentReadModel');
const ProjectionCheckpoint = require('../models/ProjectionCheckpoint');
const eventBus = require('../services/eventBus');
const { apply, initialState } = require('../domain/shipment');

const CHECKPOINT_NAME = 'shipment-read-model';
const POLL_BATCH = 500;
// ObjectIds are generated by the app server, so two instances can commit slightly out of _id order.
// Re-scanning a small window behind the checkpoint makes the poller tolerant of that.
const RESCAN_WINDOW_SECONDS = 60;
const MAX_CAS_ATTEMPTS = 5;

const iso = (v) => (v == null ? null : new Date(v).toISOString());

function stateFromReadModel(doc) {
  return {
    shipmentId: doc.shipmentId,
    exists: true,
    status: doc.status,
    version: doc.version,
    createdAt: iso(doc.createdAt),
    lastEventAt: iso(doc.lastEventAt),
    origin: doc.origin ?? null,
    destination: doc.destination ?? null,
    vessel: doc.vessel ?? null,
    currentTemperature: doc.currentTemperature ?? null,
    maxTemperature: doc.maxTemperature ?? null,
    spikeCount: doc.spikeCount ?? 0,
    eventCount: doc.eventCount,
    lastHash: doc.lastHash ?? null,
  };
}

function readModelFields(state) {
  const { shipmentId, status, version, eventCount, origin, destination, vessel, currentTemperature, maxTemperature, spikeCount, createdAt, lastEventAt, lastHash } = state;
  return { shipmentId, status, version, eventCount, origin, destination, vessel, currentTemperature, maxTemperature, spikeCount, createdAt, lastEventAt, lastHash };
}

/**
 * Brings one aggregate's read-model row up to date. Idempotent and safe to run concurrently:
 * the row is only written if nobody else advanced it first (compare-and-set on `version`).
 */
async function projectAggregate(aggregateId) {
  for (let attempt = 0; attempt < MAX_CAS_ATTEMPTS; attempt += 1) {
    const row = await ShipmentReadModel.findOne({ shipmentId: aggregateId }).lean();
    let state = row ? stateFromReadModel(row) : initialState(aggregateId);

    let events = await EventStore.find({ aggregateId, version: { $gt: state.version } }).sort({ version: 1 }).lean();
    if (!events.length) return state.exists ? state : null;

    if (events[0].version !== state.version + 1) {
      // The row is inconsistent with the stream (e.g. restored backup): rebuild this aggregate from scratch.
      state = initialState(aggregateId);
      events = await EventStore.find({ aggregateId }).sort({ version: 1 }).lean();
    }

    state = events.reduce(apply, state);
    const fields = readModelFields(state);

    try {
      if (row) {
        const result = await ShipmentReadModel.updateOne({ shipmentId: aggregateId, version: row.version }, { $set: fields });
        if (result.matchedCount === 0) continue; // someone else advanced the row first; re-read
      } else {
        await ShipmentReadModel.create(fields);
      }
      return state;
    } catch (error) {
      if (error?.code === 11000) continue; // concurrent insert of the same row
      throw error;
    }
  }
  throw new Error(`Could not project ${aggregateId}: too much contention`);
}

class ProjectionWorker {
  constructor({ pollMs = 2000, logger = console } = {}) {
    this.pollMs = pollMs;
    this.logger = logger;
    this.pending = new Set();
    this.running = null;
    this.timer = null;
    this.onAppended = ({ aggregateId }) => this.enqueue(aggregateId);
  }

  start() {
    if (this.timer) return;
    eventBus.on('event.appended', this.onAppended);
    const tick = () => this.catchUp().catch((e) => this.logger.error('projection poll failed:', e.message));
    this.timer = setInterval(tick, this.pollMs);
    this.timer.unref();
    tick();
  }

  stop() {
    eventBus.off('event.appended', this.onAppended);
    clearInterval(this.timer);
    this.timer = null;
  }

  enqueue(aggregateId) {
    this.pending.add(aggregateId);
    this.pump();
  }

  pump() {
    if (this.running) return this.running;
    this.running = (async () => {
      while (this.pending.size) {
        const [id] = this.pending;
        this.pending.delete(id);
        try {
          await projectAggregate(id);
        } catch (error) {
          this.logger.error(`projection of ${id} failed:`, error.message);
        }
      }
    })().finally(() => {
      this.running = null;
    });
    return this.running;
  }

  /** Scans events written since the checkpoint and projects every aggregate they touch. */
  async catchUp() {
    const checkpoint = await ProjectionCheckpoint.findOne({ name: CHECKPOINT_NAME }).lean();
    let filter = {};
    if (checkpoint?.lastEventId) {
      const seconds = Math.floor(checkpoint.lastEventId.getTimestamp().getTime() / 1000);
      filter = { _id: { $gt: mongoose.Types.ObjectId.createFromTime(Math.max(0, seconds - RESCAN_WINDOW_SECONDS)) } };
    }

    let lastSeen = checkpoint?.lastEventId ?? null;
    for (;;) {
      const batch = await EventStore.find(filter).sort({ _id: 1 }).limit(POLL_BATCH).select('aggregateId').lean();
      if (!batch.length) break;
      batch.forEach((e) => this.pending.add(e.aggregateId));
      lastSeen = batch[batch.length - 1]._id;
      filter = { _id: { $gt: lastSeen } };
      await this.pump();
      if (batch.length < POLL_BATCH) break;
    }
    await this.pump();

    if (lastSeen) {
      await ProjectionCheckpoint.updateOne({ name: CHECKPOINT_NAME }, { $set: { lastEventId: lastSeen } }, { upsert: true });
    }
  }

  /** Waits until everything currently known has been projected (used by tests and shutdown). */
  async flush() {
    await this.catchUp();
    while (this.running || this.pending.size) await this.pump();
  }

  /** Drops the read model and replays the whole event log into it. */
  async rebuildAll() {
    await ShipmentReadModel.deleteMany({});
    await ProjectionCheckpoint.deleteOne({ name: CHECKPOINT_NAME });
    const ids = await EventStore.distinct('aggregateId');
    ids.forEach((id) => this.pending.add(id));
    await this.pump();
    await this.catchUp();
    return ids.length;
  }
}

module.exports = { ProjectionWorker, projectAggregate, stateFromReadModel };
